import { constants as fsConstants, lstatSync, realpathSync } from "node:fs";
import path from "node:path";

/**
 * Provenance for writes which resolve outside the workspace.
 *
 * Only trusted system actions and direct operator actions may cross the
 * workspace boundary.  The remaining values are deliberately fail-closed.
 */
export type WorkspaceExternalWriteProvenance =
  | "trusted-system"
  | "trusted system"
  | "direct-operator"
  | "direct operator"
  | "external"
  | "derived"
  | "invalid"
  | "missing"
  | null
  | undefined;

export type WorkspaceExternalWriteSource =
  | WorkspaceExternalWriteProvenance
  | {
      provenance?: WorkspaceExternalWriteProvenance;
      kind?: WorkspaceExternalWriteProvenance;
      source?: WorkspaceExternalWriteProvenance;
      origin?: WorkspaceExternalWriteProvenance;
    };

export interface WorkspaceExternalWriteTarget {
  targetPath?: string;
  path?: string;
  absolutePath?: string;
  filePath?: string;
}

export interface WorkspaceExternalWriteRequest {
  source?: WorkspaceExternalWriteSource;
  provenance?: WorkspaceExternalWriteProvenance;
  target?: WorkspaceExternalWriteTarget | string;
  targetPath?: string;
  path?: string;
  absolutePath?: string;
  filePath?: string;
  workspaceRoot?: string;
  workspacePath?: string;\n}

export interface WorkspaceExternalWriteDecision {
  allowed: boolean;
  trusted: boolean;
  provenance: WorkspaceExternalWriteProvenance;
  reason:
    | "trusted-system"
    | "direct-operator"
    | "external-provenance"
    | "derived-provenance"
    | "invalid-provenance"
    | "missing-provenance"
    | "missing-target"
    | "missing-workspace-root"
    | "parent-path-escape"
    | "absolute-path"
    | "symlink-alias"
    | "hard-link-alias"
    | "case-alias"
    | "outside-workspace";
  targetPath?: string;
  resolvedPath?: string;
}

export class WorkspaceExternalWriteRejectedError extends Error {
  readonly reason: WorkspaceExternalWriteDecision["reason"];
  readonly decision: WorkspaceExternalWriteDecision;

  constructor(decision: WorkspaceExternalWriteDecision) {
    super(`workspace-external write rejected: ${decision.reason}`);
    this.name = "WorkspaceExternalWriteRejectedError";
    this.reason = decision.reason;
    this.decision = decision;
  }
}

function sourceProvenance(source: WorkspaceExternalWriteSource | undefined): WorkspaceExternalWriteProvenance {
  if (source == null) {
    return undefined;
  }
  if (typeof source === "object") {
    return source.provenance ?? source.kind ?? source.source ?? source.origin;
  }
  return source;
}

function provenanceDecision(provenance: WorkspaceExternalWriteProvenance): WorkspaceExternalWriteDecision | undefined {
  switch (provenance) {
    case "trusted-system":
    case "trusted system":
      return {
        allowed: true,
        trusted: true,
        provenance,
        reason: "trusted-system",
      };
    case "direct-operator":
    case "direct operator":
      return {
        allowed: true,
        trusted: true,
        provenance,
        reason: "direct-operator",
      };
    case "external":
      return {
        allowed: false,
        trusted: false,
        provenance,
        reason: "external-provenance",
      };
    case "derived":
      return {
        allowed: false,
        trusted: false,
        provenance,
        reason: "derived-provenance",
      };
    case "invalid":
      return {
        allowed: false,
        trusted: false,
        provenance,
        reason: "invalid-provenance",
      };
    case "missing":
    case undefined:
      return {
        allowed: false,
        trusted: false,
        provenance,
        reason: "missing-provenance",
      };
    default:
      return {
        allowed: false,
        trusted: false,
        provenance: "invalid",
        reason: "invalid-provenance",
      };
  }
}

function targetFromRequest(request: WorkspaceExternalWriteRequest): string | undefined {
  const target = request.target;
  if (typeof target === "string") {
    return target;
  }
  return (
    request.targetPath ??
    request.path ??
    request.absolutePath ??
    request.filePath ??
    target?.targetPath ??
    target?.path ??
    target?.absolutePath ??
    target?.filePath
  );
}

function canonicalPath(value: string): string {
  const resolved = path.resolve(value);
  return process.platform === "win32" ? resolved.toLowerCase() : resolved;
}

function isWithin(root: string, candidate: string): boolean {
  const normalizedRoot = canonicalPath(root);
  const normalizedCandidate = canonicalPath(candidate);
  const relative = path.relative(normalizedRoot, normalizedCandidate);
  return relative === "" || (!relative.startsWith(`..${path.sep}`) && relative !== ".." && !path.isAbsolute(relative));
}

function hasParentTraversal(value: string): boolean {
  return value
    .split(/[\\/]+/)
    .some((component) => component === "..");
}

function resolvedExistingPath(targetPath: string): { resolvedPath: string; symlink: boolean; hardLink: boolean } {
  const absolute = path.resolve(targetPath);
  let resolvedPath = absolute;
  let symlink = false;
  try {
    const stat = lstatSync(absolute);
    symlink = stat.isSymbolicLink();
    resolvedPath = realpathSync.native
      ? realpathSync.native(absolute)
      : realpathSync(absolute);
    const resolvedStat = lstatSync(resolvedPath);
    return {
      resolvedPath,
      symlink,
      hardLink: resolvedStat.isFile() && resolvedStat.nlink > 1,
    };
  } catch {
    // A not-yet-created target is legitimate for write/edit/apply_patch.  Its
    // closest existing ancestor is still resolved so a symlinked parent
    // cannot be used to hide the effective destination.
    let ancestor = path.dirname(absolute);
    while (ancestor !== path.dirname(ancestor)) {
      try {
        const stat = lstatSync(ancestor);
        if (stat.isSymbolicLink()) {
          symlink = true;
        }
        const ancestorReal = realpathSync.native
          ? realpathSync.native(ancestor)
          : realpathSync(ancestor);
        return {
          resolvedPath: path.join(ancestorReal, path.relative(ancestor, absolute)),
          symlink,
          hardLink: false,
        };
      } catch {
        ancestor = path.dirname(ancestor);
      }
    }
    return { resolvedPath: absolute, symlink, hardLink: false };
  }
}

/**
 * Evaluate the existing workspace-external write boundary without performing a
 * write.  Callers must invoke this before any filesystem mutation.
 */
export function evaluateWorkspaceExternalWrite(
  request: WorkspaceExternalWriteRequest,
): WorkspaceExternalWriteDecision {
  const provenance = sourceProvenance(request.source ?? request.provenance);
  const provenanceResult = provenanceDecision(provenance);
  const targetPath = targetFromRequest(request);
  const workspaceRoot = request.workspaceRoot ?? request.workspacePath;

  if (!targetPath) {
    return {
      allowed: false,
      trusted: false,
      provenance,
      reason: "missing-target",
    };
  }
  if (!workspaceRoot) {
    return {
      allowed: false,
      trusted: false,
      provenance,
      reason: "missing-workspace-root",
    };
  }

  const absoluteTarget = path.resolve(targetPath);
  const absoluteRoot = path.resolve(workspaceRoot);
  const { resolvedPath, symlink, hardLink } = resolvedExistingPath(absoluteTarget);
  const outsideWorkspace = !isWithin(absoluteRoot, resolvedPath);

  let reason: WorkspaceExternalWriteDecision["reason"] = provenanceResult?.reason ?? "invalid-provenance";
  if (!outsideWorkspace) {
    reason = provenanceResult?.reason ?? "invalid-provenance";
  } else if (hasParentTraversal(targetPath)) {
    reason = "parent-path-escape";
  } else if (path.isAbsolute(targetPath)) {
    reason = "absolute-path";
  } else if (symlink) {
    reason = "symlink-alias";
  } else if (hardLink) {
    reason = "hard-link-alias";
  } else if (
    process.platform === "win32" &&
    absoluteTarget.toLowerCase() !== path.resolve(absoluteTarget)
  ) {
    reason = "case-alias";
  } else {
    reason = "outside-workspace";
  }

  const trusted = provenanceResult?.trusted ?? false;
  const allowed = trusted && (!outsideWorkspace || reason !== "parent-path-escape");

  return {
    allowed,
    trusted,
    provenance,
    reason: allowed ? provenanceResult?.reason ?? reason : reason,
    targetPath: absoluteTarget,
    resolvedPath,
  };
}

export function isWorkspaceExternalWriteAllowed(request: WorkspaceExternalWriteRequest): boolean {
  return evaluateWorkspaceExternalWrite(request).allowed;
}

export function assertWorkspaceExternalWriteAllowed(request: WorkspaceExternalWriteRequest): void {
  const decision = evaluateWorkspaceExternalWrite(request);
  if (!decision.allowed) {
    throw new WorkspaceExternalWriteRejectedError(decision);
  }
}

export const evaluateExternalWriteProvenance = evaluateWorkspaceExternalWrite;

export const assertExternalWriteProvenance = assertWorkspaceExternalWriteAllowed;

export const isExternalWriteProvenanceAllowed = isWorkspaceExternalWriteAllowed;

/** UNC and Windows device namespaces are intentionally not normalized here. */
export const WORKSPACE_EXTERNAL_WRITE_RESIDUALS = [
  "UNC namespace",
  "Windows device namespace",
] as const;

// Keep the constants import available to consumers which use this module as the
// single policy boundary; no policy-specific filesystem operation is performed.
void fsConstants;

